import{_ as o,l as c,o as a,c as s,v as r,p,x as t,d as l,i,S as n}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"MapReduce","description":"","frontmatter":{"title":"MapReduce","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mapreduce.md","filePath":"cs/mapreduce.md","lastUpdated":1789023840000}'),u={name:"cs/mapreduce.md"};function h(m,e,f,_,S,k){const d=c("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="mapreduce" tabindex="-1">MapReduce <a class="header-anchor" href="#mapreduce" aria-label="Permalink to &quot;MapReduce&quot;">​</a></h1><div class="epigraph"><p>把批处理收成 map 与 reduce 两次用户函数，中间用按键分区的排序连接；容错靠再执行任务，不靠分布式共享内存。</p><footer>—— Dean and Ghemawat, MapReduce, OSDI 2004 / CACM 2008</footer></div><p><a href="/cs/lakehouse-table-format">上一课</a>给出可共享的表快照。缺口是<strong>如何在上千台机器上算</strong>：不是新 SQL，是把函数接到分区洗牌。本课钉 MapReduce；Spark DAG 下一课去掉强制的两阶段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全表扫描 + 分组聚合：map 发射 <code>(k,v)</code>，shuffle 按 <code>k</code> 聚集，reduce 做合计。缺口是调度与容错：一台 map 挂了，只重跑该分片；reduce 读的是持久化的中间文件。没有这套模型，湖上的文件只是静态。与并行 DBMS：MR 当初用松 schema 与廉价硬件换计划质量。</p><p><span class="marginnote">GFS 提供分片与复制。combiner 是可选的本地预聚合。记录条数不是负载：倾斜键会把一个 reduce 打满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入分片 → map → 溢写排序 → 按分区拷到 reduce → 归并 → 输出。推测执行对付拖后腿。与湖仓：输入可以是表快照的文件清单。计数、倒排、连接（map 端或 reduce 端）都是同一骨架上的程序。</p>',8)),(a(),p(n,null,{default:t(()=>[i(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%88%86%E7%89%87%22%5D%20--%3E%20M%5B%22map%22%5D%0A%20%20M%20--%3E%20SH%5B%22shuffle%20%2F%20%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SH%20--%3E%20R%5B%22reduce%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>确定性的纯 map/reduce 使再执行等价于第一次。副作用（写外部）会打破这点——后课恰好一次要处理 sink。shuffle 是全对全的带宽税，也是倾斜的放大器：一键一个 reduce 打满，与 <a href="/cs/grace-hash-join">Grace hash join</a> 的热键同构。combiner 在 map 端预聚合，像两阶段哈希聚合的 local agg。</p><p>输出提交常用目录改名当原子，像切根。与并行数据库：MR 当初用松 schema 与廉价硬件换计划质量；SQL-on-Hadoop 后来把 GROUP BY 编译回同一骨架。推测执行对付拖后腿机器，不修复倾斜。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Hadoop 配置百科。下一课 DAG 允许多阶段与内存缓存，避免每次强制物化两跳。不把 MR 当流处理：窗口与 watermark 是后课。图迭代用多次作业很笨，那是 Spark 动机。</p><p>后课默认：批 shuffle 可理解成 MR；迭代与流水用 DAG。连接仍是 map-side 广播或 reduce-side 按键碰面。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MapReduce：分片函数 + 按键洗牌 + 再执行容错。</li><li>倾斜与 shuffle 是主要代价；combiner 减流量。</li><li>Spark 与 DAG 下一课。</li><li>出处：Dean and Ghemawat, MapReduce, OSDI 2004。</li></ul>',8))])}const D=o(u,[["render",h]]);export{b as __pageData,D as default};
